+      <span><i class="dot" style="background:#ff6b6b"></i> -weight</span>
+    </div>
+  </div>
+
+  <div class="panel controls">
+    <div class="field">
+      <label>Dataset</label>
+      <select id="dataset">
+        <option value="xor">XOR</option>
+        <option value="circle">Circle</option>
+        <option value="spiral" selected>Spiral (hard)</option>
+        <option value="linear">Linear</option>
+      </select>
+    </div>
+    <div class="field">
+      <label>Hidden layer sizes: <span id="archLabel">8, 8</span></label>
+      <select id="arch">
+        <option value="4">4</option>
+        <option value="8,8" selected>8, 8</option>
+        <option value="16,16">16, 16</option>
+        <option value="16,16,16">16, 16, 16</option>
+      </select>
+    </div>
+    <div class="field">
