+(function () {
+  const vizCanvas = document.getElementById('viz');
+  const vctx = vizCanvas.getContext('2d');
+  const lossCanvas = document.getElementById('lossCanvas');
+  const lctx = lossCanvas.getContext('2d');
+  const netCanvas = document.getElementById('netCanvas');
+  const nctx = netCanvas.getContext('2d');
+  const W = vizCanvas.width, H = vizCanvas.height;
+
+  const datasetSel = document.getElementById('dataset');
+  const archSel = document.getElementById('arch');
+  const lrRange = document.getElementById('lr');
+  const lrLabel = document.getElementById('lrLabel');
+  const playBtn = document.getElementById('playBtn');
+  const resetBtn = document.getElementById('resetBtn');
+  const epochEl = document.getElementById('epoch');
+  const lossEl = document.getElementById('loss');
+  const accEl = document.getElementById('acc');
+
+  let net, data, epoch, lossHistory, playing = true;
+
+  function coordToPixel(x, y) {
+    return [ (x + 1) / 2 * W, (1 - (y + 1) / 2) * H ];
+  }
+
+  function build() {
+    const hidden = archSel.value.split(',').map(Number);
+    net = new NN.Network([2, ...hidden, 1], 'tanh', 'sigmoid');
+    data = NN.makeDataset(datasetSel.value, 240);
+    epoch = 0;
+    lossHistory = [];
+    epochEl.textContent = '0';
+    lossEl.textContent = '-';
+    accEl.textContent = '-';
+  }
+
+  function accuracy() {
+    let correct = 0;
+    for (const [x, y] of data) {
+      const pred = net.predict(x)[0] >= 0.5 ? 1 : 0;
+      if (pred === y[0]) correct++;
+    }
+    return correct / data.length;
+  }
+
+  function drawBoundary() {
+    const res = 48;
+    const cellW = W / res, cellH = H / res;
+    for (let j = 0; j < res; j++) {
+      for (let i = 0; i < res; i++) {
+        const x = (i / res) * 2 - 1;
+        const y = 1 - (j / res) * 2;
+        const p = net.predict([x, y])[0];
+        // interpolate between red (0) and blue (1)
+        const r = Math.round(255 * (1 - p) * 0.55 + 20);
+        const b = Math.round(255 * p * 0.55 + 20);
+        vctx.fillStyle = `rgb(${r},20,${b})`;
+        vctx.fillRect(i * cellW, j * cellH, cellW + 1, cellH + 1);
+      }
+    }
+  }
+
+  function drawPoints() {
+    for (const [x, y] of data) {
+      const [px, py] = coordToPixel(x[0], x[1]);
+      vctx.beginPath();
+      vctx.arc(px, py, 4, 0, Math.PI * 2);
+      vctx.fillStyle = y[0] === 1 ? '#5ac8fa' : '#ff6b6b';
