+    const sizes = [net.layers[0].inSize, ...net.layers.map((l) => l.outSize)];
+    const nLayers = sizes.length;
+    const colX = sizes.map((_, i) => (cw / (nLayers - 1)) * i);
+    // clamp margins so first/last columns aren't clipped
+    colX[0] = 26; colX[nLayers - 1] = cw - 26;
+    for (let i = 1; i < nLayers - 1; i++) {
+      colX[i] = 26 + ((cw - 52) / (nLayers - 1)) * i;
+    }
+    const nodeY = sizes.map((n) =>
+      Array.from({ length: n }, (_, k) => (ch / (n + 1)) * (k + 1))
+    );
