+    font-size: 12px;
+    color: var(--muted);
+    margin-bottom: 4px;
+    text-transform: uppercase;
+    letter-spacing: 0.04em;
+  }
+  select, input[type=range] { width: 100%; }
+  select {
+    background: #0e131c;
+    color: var(--text);
+    border: 1px solid var(--border);
+    border-radius: 6px;
+    padding: 6px 8px;
+  }
+  .row { display: flex; gap: 8px; }
+  button {
+    flex: 1;
+    background: linear-gradient(180deg, #1c2534, #141b28);
+    color: var(--text);
+    border: 1px solid var(--border);
+    border-radius: 6px;
+    padding: 10px 12px;
+    cursor: pointer;
+    font-weight: 600;
+    font-size: 13px;
+  }
+  button:hover { border-color: var(--accent); }
+  button.primary { background: linear-gradient(180deg, #2c7fb8, #1e5c8a); border-color: #2c7fb8; }
+  .stat { display: flex; justify-content: space-between; font-size: 13px; padding: 4px 0; }
+  .stat b { color: var(--accent); }
+  #lossCanvas { width: 100%; height: 90px; background: #05070c; border-radius: 6px; }
+  footer { padding: 10px 24px; color: var(--muted); font-size: 12px; border-top: 1px solid var(--border); }
+  .legend { display:flex; gap:16px; font-size:12px; color: var(--muted); margin-top: 6px;}
+  .legend span { display:flex; align-items:center; gap:6px; }
+  .dot { width:10px; height:10px; border-radius:50%; display:inline-block; }
+</style>
+</head>
+<body>
+<header>
+  <h1>🧠 NN Playground</h1>
+  <span>a from-scratch, zero-dependency neural network trained live in your browser</span>
+</header>
+<main>
+  <div class="panel" id="canvasWrap">
+    <canvas id="viz" width="520" height="520"></canvas>
+    <div class="legend">
+      <span><i class="dot" style="background:#ff6b6b"></i> class 0</span>
+      <span><i class="dot" style="background:#5ac8fa"></i> class 1</span>
+      <span>background = learned decision surface</span>
+    </div>
+    <div class="legend" style="margin-top:2px">
+      <span><b style="color:#e6e9ef">Click</b>&nbsp;canvas = add blue point &nbsp;·&nbsp; <b style="color:#e6e9ef">Right-click</b> = add red point</span>
+    </div>
+  </div>
+
+  <div class="panel" id="netWrap">
+    <canvas id="netCanvas" width="260" height="520"></canvas>
+    <div class="legend" style="flex-wrap:wrap">
+      <span><i class="dot" style="background:#5ac8fa"></i> +weight</span>
+      <span><i class="dot" style="background:#ff6b6b"></i> -weight</span>
+      <span><i class="dot" style="background:#f5c26b"></i> input</span>
+      <span><i class="dot" style="background:#7cffb2"></i> output</span>
+    </div>
+  </div>
+
+  <div class="panel controls">
+    <div class="field">
+      <label>Dataset</label>
+      <select id="dataset">
+        <option value="xor">XOR</option>
+        <option value="circle">Circle</option>
+        <option value="spiral" selected>Spiral (hard)</option>
+        <option value="linear">Linear</option>
+      </select>
+    </div>
+    <div class="field">
+      <label>Hidden layer sizes: <span id="archLabel">8, 8</span></label>
+      <select id="arch">
+        <option value="4">4</option>
+        <option value="8,8" selected>8, 8</option>
+        <option value="16,16">16, 16</option>
+        <option value="16,16,16">16, 16, 16</option>
+      </select>
+    </div>
+    <div class="field">
+      <label>Learning rate: <span id="lrLabel">0.30</span></label>
+      <input type="range" id="lr" min="0.01" max="1" step="0.01" value="0.3" />
+    </div>
+    <div class="row">
+      <button id="playBtn" class="primary">⏸ Pause</button>
+      <button id="resetBtn">↻ Reset</button>
+    </div>
+    <div>
+      <div class="stat">Epoch <b id="epoch">0</b></div>
+      <div class="stat">Loss <b id="loss">-</b></div>
+      <div class="stat">Accuracy <b id="acc">-</b></div>
+    </div>
+    <div class="field">
+      <label>Loss curve</label>
+      <canvas id="lossCanvas" width="280" height="90"></canvas>
+    </div>
+  </div>
+</main>
+<footer>
+  Pure JavaScript, no frameworks, no build step, no external dependencies. Backprop engine in <code>src/nn.js</code> is unit-tested with <code>npm test</code>. Built by agent D.
+</footer>
+
+<script src="src/nn.js"></script>
+<script>
+(function () {
+  const vizCanvas = document.getElementById('viz');
+  const vctx = vizCanvas.getContext('2d');
+  const lossCanvas = document.getElementById('lossCanvas');
+  const lctx = lossCanvas.getContext('2d');
+  const netCanvas = document.getElementById('netCanvas');
+  const nctx = netCanvas.getContext('2d');
+  const W = vizCanvas.width, H = vizCanvas.height;
+
+  const datasetSel = document.getElementById('dataset');
+  const archSel = document.getElementById('arch');
+  const lrRange = document.getElementById('lr');
+  const lrLabel = document.getElementById('lrLabel');
+  const playBtn = document.getElementById('playBtn');
+  const resetBtn = document.getElementById('resetBtn');
+  const epochEl = document.getElementById('epoch');
+  const lossEl = document.getElementById('loss');
+  const accEl = document.getElementById('acc');
+
+  let net, data, epoch, lossHistory, playing = true;
+
+  function coordToPixel(x, y) {
+    return [ (x + 1) / 2 * W, (1 - (y + 1) / 2) * H ];
+  }
+
+  function pixelToCoord(px, py) {
+    return [ (px / W) * 2 - 1, 1 - (py / H) * 2 ];
+  }
+
+  function build() {
+    const hidden = archSel.value.split(',').map(Number);
+    net = new NN.Network([2, ...hidden, 1], 'tanh', 'sigmoid');
+    data = NN.makeDataset(datasetSel.value, 240);
+    epoch = 0;
+    lossHistory = [];
+    epochEl.textContent = '0';
+    lossEl.textContent = '-';
+    accEl.textContent = '-';
+  }
+
+  function accuracy() {
+    let correct = 0;
+    for (const [x, y] of data) {
+      const pred = net.predict(x)[0] >= 0.5 ? 1 : 0;
+      if (pred === y[0]) correct++;
+    }
+    return correct / data.length;
+  }
+
+  function drawBoundary() {
+    const res = 48;
+    const cellW = W / res, cellH = H / res;
+    for (let j = 0; j < res; j++) {
+      for (let i = 0; i < res; i++) {
+        const x = (i / res) * 2 - 1;
+        const y = 1 - (j / res) * 2;
+        const p = net.predict([x, y])[0];
+        // interpolate between red (0) and blue (1)
+        const r = Math.round(255 * (1 - p) * 0.55 + 20);
+        const b = Math.round(255 * p * 0.55 + 20);
+        vctx.fillStyle = `rgb(${r},20,${b})`;
+        vctx.fillRect(i * cellW, j * cellH, cellW + 1, cellH + 1);
+      }
+    }
+  }
+
+  function drawPoints() {
+    for (const [x, y] of data) {
+      const [px, py] = coordToPixel(x[0], x[1]);
+      vctx.beginPath();
+      vctx.arc(px, py, 4, 0, Math.PI * 2);
+      vctx.fillStyle = y[0] === 1 ? '#5ac8fa' : '#ff6b6b';
+      vctx.strokeStyle = 'rgba(0,0,0,0.5)';
+      vctx.lineWidth = 1;
+      vctx.fill();
+      vctx.stroke();
+    }
+  }
+
+  function drawLoss() {
+    lctx.clearRect(0, 0, lossCanvas.width, lossCanvas.height);
+    if (lossHistory.length < 2) return;
+    const maxLoss = Math.max(...lossHistory, 0.01);
+    lctx.beginPath();
+    lctx.strokeStyle = '#5ac8fa';
+    lctx.lineWidth = 2;
+    lossHistory.forEach((l, i) => {
+      const x = (i / (lossHistory.length - 1)) * lossCanvas.width;
+      const y = lossCanvas.height - (l / maxLoss) * lossCanvas.height;
+      if (i === 0) lctx.moveTo(x, y); else lctx.lineTo(x, y);
+    });
+    lctx.stroke();
+  }
+
+  function drawNetworkDiagram() {
+    const cw = netCanvas.width, ch = netCanvas.height;
+    nctx.clearRect(0, 0, cw, ch);
+    // layer sizes: input (2) -> each Dense layer's outSize
+    const sizes = [net.layers[0].inSize, ...net.layers.map((l) => l.outSize)];
+    const nLayers = sizes.length;
+    const colX = sizes.map((_, i) => (cw / (nLayers - 1)) * i);
+    // clamp margins so first/last columns aren't clipped
+    colX[0] = 26; colX[nLayers - 1] = cw - 26;
+    for (let i = 1; i < nLayers - 1; i++) {
+      colX[i] = 26 + ((cw - 52) / (nLayers - 1)) * i;
+    }
+    const nodeY = sizes.map((n) =>
+      Array.from({ length: n }, (_, k) => (ch / (n + 1)) * (k + 1))
+    );
+
+    // edges first (so nodes draw on top)
+    net.layers.forEach((layer, li) => {
+      const maxAbs = Math.max(
+        0.001,
+        ...layer.W.flat().map((w) => Math.abs(w))
+      );
+      for (let o = 0; o < layer.outSize; o++) {
+        for (let i = 0; i < layer.inSize; i++) {
+          const w = layer.W[o][i];
+          const alpha = Math.min(1, Math.abs(w) / maxAbs) * 0.85 + 0.05;
+          nctx.strokeStyle = w >= 0
+            ? `rgba(90,200,250,${alpha})`
+            : `rgba(255,107,107,${alpha})`;
+          nctx.lineWidth = Math.min(3, 0.5 + 2.5 * Math.abs(w) / maxAbs);
+          nctx.beginPath();
+          nctx.moveTo(colX[li], nodeY[li][i]);
+          nctx.lineTo(colX[li + 1], nodeY[li + 1][o]);
+          nctx.stroke();
+        }
+      }
+    });
+
+    // nodes
+    for (let l = 0; l < nLayers; l++) {
+      for (let k = 0; k < sizes[l]; k++) {
+        nctx.beginPath();
+        nctx.arc(colX[l], nodeY[l][k], 7, 0, Math.PI * 2);
+        nctx.fillStyle = l === 0 ? '#f5c26b' : (l === nLayers - 1 ? '#7cffb2' : '#c9d3e0');
+        nctx.fill();
+        nctx.strokeStyle = '#05070c';
+        nctx.lineWidth = 1.5;
+        nctx.stroke();
+      }
+    }
+  }
+
+  function render() {
+    vctx.clearRect(0, 0, W, H);
+    drawBoundary();
+    drawPoints();
+    drawLoss();
+    drawNetworkDiagram();
+  }
+
+  function step() {
+    const lr = parseFloat(lrRange.value);
+    const loss = net.trainEpoch(data, lr);
+    epoch++;
+    lossHistory.push(loss);
+    if (lossHistory.length > 200) lossHistory.shift();
+    epochEl.textContent = epoch;
+    lossEl.textContent = loss.toFixed(4);
+    if (epoch % 5 === 0) accEl.textContent = (accuracy() * 100).toFixed(1) + '%';
+  }
+
+  function loop() {
+    if (playing) {
+      for (let i = 0; i < 3; i++) step(); // a few SGD epochs per frame
+      render();
+    }
+    requestAnimationFrame(loop);
+  }
+
+  // Reasonable presets per dataset so the demo looks good out of the box
+  // (spiral in particular needs a bigger net + smaller learning rate).
+  const PRESETS = {
+    xor: { arch: '8,8', lr: 0.3 },
+    circle: { arch: '8,8', lr: 0.3 },
+    spiral: { arch: '16,16', lr: 0.1 },
+    linear: { arch: '4', lr: 0.3 },
+  };
+
+  function applyPreset() {
+    const p = PRESETS[datasetSel.value];
+    if (!p) return;
+    archSel.value = p.arch;
+    document.getElementById('archLabel').textContent = p.arch;
+    lrRange.value = p.lr;
+    lrLabel.textContent = p.lr.toFixed(2);
+  }
+
+  datasetSel.addEventListener('change', () => { applyPreset(); build(); });
+  archSel.addEventListener('change', () => {
+    document.getElementById('archLabel').textContent = archSel.value;
+    build();
+  });
+  lrRange.addEventListener('input', () => { lrLabel.textContent = parseFloat(lrRange.value).toFixed(2); });
+  playBtn.addEventListener('click', () => {
+    playing = !playing;
+    playBtn.textContent = playing ? '⏸ Pause' : '▶ Play';
+  });
+  resetBtn.addEventListener('click', build);
+
+  // Interactive: let a human hand-craft the dataset and watch the network
+  // adapt live. Left click = add class 1 (blue), right click = class 0 (red).
+  function addPointFromEvent(e, label) {
+    e.preventDefault();
+    const rect = vizCanvas.getBoundingClientRect();
+    const px = (e.clientX - rect.left) * (vizCanvas.width / rect.width);
+    const py = (e.clientY - rect.top) * (vizCanvas.height / rect.height);
+    const [x, y] = pixelToCoord(px, py);
+    data.push([[x, y], [label]]);
+  }
+  vizCanvas.addEventListener('click', (e) => addPointFromEvent(e, 1));
+  vizCanvas.addEventListener('contextmenu', (e) => addPointFromEvent(e, 0));
+
+  applyPreset();
+  build();
+  render();
+  requestAnimationFrame(loop);
+})();
+</script>
+</body>
+</html>

